// Фильтр письма Min/Max: отправитель, тема, ровно один Excel.
const allowedSender = String($env.MINMAX_ALLOWED_SENDER || '').trim().toLowerCase();
const subjectPattern = String($env.MINMAX_SUBJECT_PATTERN || '').trim().toLowerCase();
const maxBytes = Number($env.MINMAX_MAX_ATTACHMENT_BYTES) || 20 * 1024 * 1024;
const mailbox = String($env.MINMAX_IMAP_MAILBOX || 'INBOX');

const from = String(($json.from && $json.from.text) || $json.from || '').toLowerCase();
const subject = String($json.subject || '');
const messageUid = String($json.uid ?? $json.messageId ?? '');
const uidValidity = String($json.uidvalidity ?? '');

const sanitize = value => {
  const cleaned = String(value ?? '')
    .replace(/[^A-Za-z0-9._:-]+/g, '_')
    .replace(/^_+|_+$/g, '');
  return (cleaned || 'na').slice(0, 180);
};
const buildKey = (attachmentName, size) => [
  'minmax',
  sanitize(mailbox),
  sanitize(uidValidity),
  sanitize(messageUid),
  sanitize(attachmentName),
  String(Number(size) || 0)
].join('-').slice(0, 512);

const base = {
  mailbox,
  messageUid,
  sender: from,
  subject,
  receivedDate: $json.date ?? null
};

if (!allowedSender || !from.includes(allowedSender)) {
  return [{ json: { ...base, outcome: 'ignored', reasonCode: 'SENDER_NOT_ALLOWED', idempotencyKey: buildKey('no-attachment', 0) } }];
}
if (!subjectPattern || !subject.toLowerCase().includes(subjectPattern)) {
  return [{ json: { ...base, outcome: 'ignored', reasonCode: 'SUBJECT_MISMATCH', idempotencyKey: buildKey('no-attachment', 0) } }];
}

const binary = $binary || {};
const names = Object.keys(binary);
if (names.length === 0) {
  return [{ json: { ...base, outcome: 'ignored', reasonCode: 'NO_ATTACHMENT', idempotencyKey: buildKey('no-attachment', 0) } }];
}
const excelNames = names.filter(name => {
  const fileName = String(binary[name]?.fileName || '').toLowerCase();
  return fileName.endsWith('.xlsx') || fileName.endsWith('.xls');
});
if (excelNames.length === 0) {
  return [{ json: { ...base, outcome: 'rejected', reasonCode: 'ATTACHMENT_TYPE_UNSUPPORTED', idempotencyKey: buildKey(binary[names[0]]?.fileName || names[0], 0) } }];
}
if (excelNames.length > 1) {
  return [{ json: { ...base, outcome: 'rejected', reasonCode: 'MULTIPLE_ATTACHMENTS', idempotencyKey: buildKey(binary[excelNames[0]]?.fileName || excelNames[0], 0) } }];
}

const binaryKey = excelNames[0];
const attachment = binary[binaryKey];
const attachmentName = String(attachment.fileName || 'report.xlsx');
let size = Number(attachment.fileSize ?? attachment.fileSizeBytes ?? 0) || 0;
let bytes = null;
if (attachment.data) {
  bytes = Buffer.from(attachment.data, 'base64');
  size = bytes.length;
}
if (size > maxBytes) {
  return [{ json: { ...base, outcome: 'rejected', reasonCode: 'ATTACHMENT_TOO_LARGE', idempotencyKey: buildKey(attachmentName, size) } }];
}
if (bytes) {
  const isXlsx = bytes.length >= 4 && bytes[0] === 0x50 && bytes[1] === 0x4b && bytes[2] === 0x03 && bytes[3] === 0x04;
  const isXls = bytes.length >= 8 && bytes[0] === 0xd0 && bytes[1] === 0xcf && bytes[2] === 0x11 && bytes[3] === 0xe0 && bytes[4] === 0xa1 && bytes[5] === 0xb1 && bytes[6] === 0x1a && bytes[7] === 0xe1;
  if (!isXlsx && !isXls) {
    return [{ json: { ...base, outcome: 'rejected', reasonCode: 'ATTACHMENT_SIGNATURE_INVALID', idempotencyKey: buildKey(attachmentName, size) } }];
  }
}

return [{
  json: {
    ...base,
    outcome: 'process',
    reasonCode: null,
    idempotencyKey: buildKey(attachmentName, size),
    attachmentName,
    attachmentSize: size,
    binaryKey,
    pollCount: 0,
    pollDeadline: 0
  },
  binary: { [binaryKey]: attachment }
}];

// Решение по реестру: upload / poll / notify / notify-error / done.
const filter = $('Отфильтровать письмо').first().json;
const record = $json && $json.data ? $json.data : null;

if (!record || !record.idempotency_key) {
  return [{ json: { ...filter, action: 'upload' } }];
}
if (record.state === 'completed' && record.run_id) {
  return [{
    json: {
      ...filter,
      action: record.notification_sent_at ? 'done' : 'notify',
      runId: record.run_id
    }
  }];
}
if (record.run_id && ['received', 'uploading', 'run_created', 'processing'].includes(record.state)) {
  return [{ json: { ...filter, action: 'poll', runId: record.run_id } }];
}
if (record.state === 'failed' && record.run_id) {
  return [{ json: { ...filter, action: 'notify-error', runId: record.run_id, runError: record.error_code } }];
}
return [{ json: { ...filter, action: 'done' } }];

// Ответ загрузки: runId (201 или replay 200) либо ошибка.
const data = $json && $json.data ? $json.data : null;
const passthrough = { ...$json };
delete passthrough.data;
delete passthrough.api_version;
delete passthrough.error;
if (data && data.run_id) {
  return [{
    json: {
      ...passthrough,
      runId: data.run_id,
      uploadReplay: data.idempotent_replay === true,
      uploadError: null
    }
  }];
}
return [{
  json: {
    ...passthrough,
    runId: null,
    uploadReplay: false,
    uploadError: ($json && $json.error && $json.error.code) || 'UPLOAD_FAILED'
  }
}];

// Оценка статуса: completed / failed / wait / timeout (без бесконечного цикла).
const timeoutSeconds = Number($env.MINMAX_POLL_TIMEOUT_SECONDS) || 900;
const data = $json && $json.data ? $json.data : null;
const status = data && data.status ? data.status : null;
const runId = (data && data.run_id) || $json.runId || null;
const pollCount = Number($json.pollCount || 0) + 1;
const now = Date.now();
const pollDeadline = Number($json.pollDeadline || 0) || now + timeoutSeconds * 1000;
let verdict;
if (status === 'completed') verdict = 'completed';
else if (status === 'failed') verdict = 'failed';
else if (!status) verdict = 'timeout';
else verdict = now >= pollDeadline ? 'timeout' : 'wait';
return [{
  json: {
    ...$json,
    runId,
    pollCount,
    pollDeadline,
    verdict,
    runError: data && data.error && data.error.code ? data.error.code : null
  }
}];

// Уведомление владельцу: ссылка на Owner Review, без автоотправки заказа.
const filter = $('Отфильтровать письмо').first().json;
const summaryResponse = $('Сводка run').first().json;
const itemsResponse = $('Счётчики решений').first().json;
const summary = summaryResponse && summaryResponse.data ? summaryResponse.data : {};
const itemsData = itemsResponse && itemsResponse.data ? itemsResponse.data : {};
const decisions = itemsData.owner_decisions || {};
const firstItem = Array.isArray(itemsData.items) && itemsData.items.length > 0 ? itemsData.items[0] : {};
const runId = $json.runId || summary.run_id || filter.runId;
const uiBase = String($env.MINMAX_OWNER_UI_BASE_URL || 'http://localhost:3210').replace(/\/$/, '');
const link = uiBase + '/?runId=' + runId;
const financial = summary.financial || {};
const lines = [
  'Отчёт Min/Max обработан AI-закупщиком.',
  '',
  'Поставщик: ' + (firstItem.supplier || '—'),
  'Файл: ' + (filter.attachmentName || '—'),
  'Дата письма: ' + (filter.receivedDate || '—'),
  'Run: ' + runId,
  'Рекомендация: ' + (financial.recommendation || '—'),
  'Позиций в отчёте: ' + (summary.sku_count ?? '—'),
  'Требуют решения владельца: ' + (decisions.needs_decision ?? 0),
  'Финансовый статус: ' + (financial.status || '—'),
  '',
  'Открыть проверку владельца: ' + link,
  '',
  'Заказ поставщику автоматически не отправляется.'
];
return [{
  json: {
    ...$json,
    runId,
    notifyTo: String($env.MINMAX_NOTIFY_EMAIL || ''),
    notifyFrom: String($env.MINMAX_SMTP_FROM || $env.MINMAX_NOTIFY_EMAIL || ''),
    notifySubject: 'Min/Max: отчёт обработан (' + runId + ')',
    notifyText: lines.join('\n')
  }
}];

// Письмо об ошибке: письмо НЕ отмечается успешным, дубликат run невозможен.
const filter = $('Отфильтровать письмо').first().json;
const reasonCode = $json.uploadError || $json.runError || $json.reasonCode || ($json.verdict === 'timeout' ? 'POLL_TIMEOUT' : 'UNKNOWN_ERROR');
const lines = [
  'AI-закупщик не смог обработать письмо Min/Max.',
  '',
  'Файл: ' + (filter.attachmentName || '—'),
  'Письмо UID: ' + (filter.messageUid || '—'),
  'Код ошибки: ' + reasonCode,
  'Idempotency key: ' + (filter.idempotencyKey || '—'),
  '',
  'Письмо НЕ отмечено как успешно обработанное.',
  'Повторная обработка безопасна: дубликат run не будет создан (idempotency key).'
];
return [{
  json: {
    ...$json,
    errorCode: reasonCode,
    notifyTo: String($env.MINMAX_NOTIFY_EMAIL || ''),
    notifyFrom: String($env.MINMAX_SMTP_FROM || $env.MINMAX_NOTIFY_EMAIL || ''),
    notifySubject: 'Min/Max: ошибка обработки письма (' + reasonCode + ')',
    notifyText: lines.join('\n')
  }
}];
